"""
タプル・ベクトル演算 & 幾何ユーティリティ (Tuple & Vector Operations)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
グリッド座標や多次元ベクトルの加算・減算・距離計算・回転を簡潔に行う関数群。
- t_add(a, b): ベクトルの要素ごとの加算 a + b
- t_sub(a, b): ベクトルの要素ごとの減算 a - b
- t_scale(a, k): スカラー倍 k * a
- manhattan(a, b): マンハッタン距離
- chebyshev(a, b): チェビシェフ距離
- rot90_vec(x, y): 原点中心に反時計回り90度回転 (-y, x)
"""

# https://github.com/ddfkit/acsampl/blob/main/tuple.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def t_add(a,b):return tuple(x+y for x,y in zip(a,b))

# https://github.com/ddfkit/acsampl/blob/main/tuple.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def t_sub(a,b):return tuple(x-y for x,y in zip(a,b))

# https://github.com/ddfkit/acsampl/blob/main/tuple.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def t_scale(a,k):return tuple(x*k for x in a)

# https://github.com/ddfkit/acsampl/blob/main/tuple.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def manhattan(a,b):return sum(abs(x-y) for x,y in zip(a,b))

# https://github.com/ddfkit/acsampl/blob/main/tuple.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def rot90_vec(x,y):return (-y,x)

if __name__ == "__main__":
    p1 = (1, 2)
    p2 = (3, -1)
    assert t_add(p1, p2) == (4, 1)
    assert t_sub(p1, p2) == (-2, 3)
    assert t_scale(p1, 3) == (3, 6)
    assert manhattan(p1, p2) == abs(1 - 3) + abs(2 - (-1))  # 2 + 3 = 5
    assert rot90_vec(1, 0) == (0, 1)
    print("tuple.py: tests passed!")